package com.pluginideahub.npctracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class WanderProfilerTest
{
	@Test
	public void returnsNullBeforeAnySample()
	{
		assertNull(new WanderProfiler().toProfile());
	}

	@Test
	public void singleTileHasZeroRadiusAndIsItsOwnSpawn()
	{
		WanderProfiler profiler = new WanderProfiler();
		profiler.record(3005, 3204, 0);

		WanderProfile profile = profiler.toProfile();
		assertEquals(3005, profile.getSpawnX());
		assertEquals(3204, profile.getSpawnY());
		assertEquals(0, profile.getPlane());
		assertEquals(0, profile.getRadius());
		assertEquals(1, profile.getSampleCount());
	}

	@Test
	public void spawnIsCentreOfBoundingBoxAndRadiusIsChebyshevHalfWidth()
	{
		WanderProfiler profiler = new WanderProfiler();
		// A spread of 10 tiles east-west and 8 north-south, centred on (3005, 3204).
		profiler.record(3000, 3204, 0);
		profiler.record(3010, 3204, 0);
		profiler.record(3005, 3200, 0);
		profiler.record(3005, 3208, 0);

		WanderProfile profile = profiler.toProfile();
		assertEquals(3005, profile.getSpawnX());
		assertEquals(3204, profile.getSpawnY());
		assertEquals(5, profile.getRadius());
		assertEquals(4, profile.getSampleCount());
	}

	@Test
	public void radiusGrowsAsFurtherTilesAreSeen()
	{
		WanderProfiler profiler = new WanderProfiler();
		profiler.record(3000, 3200, 0);
		assertEquals(0, profiler.toProfile().getRadius());

		profiler.record(3002, 3200, 0);
		assertEquals(1, profiler.toProfile().getRadius());

		profiler.record(3000, 3206, 0);
		assertEquals(3, profiler.toProfile().getRadius());
	}

	@Test
	public void changingPlaneStartsAFreshBox()
	{
		WanderProfiler profiler = new WanderProfiler();
		profiler.record(3000, 3200, 0);
		profiler.record(3010, 3210, 0);
		profiler.record(2500, 3300, 1); // different plane -> reset

		WanderProfile profile = profiler.toProfile();
		assertEquals(1, profile.getPlane());
		assertEquals(2500, profile.getSpawnX());
		assertEquals(3300, profile.getSpawnY());
		assertEquals(0, profile.getRadius());
		assertEquals(1, profile.getSampleCount());
	}

	@Test
	public void resetClearsAllData()
	{
		WanderProfiler profiler = new WanderProfiler();
		profiler.record(3000, 3200, 0);
		profiler.reset();

		assertNull(profiler.toProfile());
		assertEquals(0, profiler.getSampleCount());
	}

	@Test
	public void tracksDistinctWalkedTiles()
	{
		WanderProfiler profiler = new WanderProfiler();
		profiler.record(3000, 3200, 0);
		profiler.record(3001, 3200, 0);
		profiler.record(3000, 3200, 0); // repeat is de-duplicated

		assertEquals(2, profiler.toProfile().getWalkedTiles().length);
	}

	@Test
	public void tilePackingRoundTrips()
	{
		long packed = WanderProfile.packTile(3211, 3888);
		assertEquals(3211, WanderProfile.tileX(packed));
		assertEquals(3888, WanderProfile.tileY(packed));
	}

	@Test
	public void exportedStateRestoresBoxSamplesAndTiles()
	{
		WanderProfiler profiler = new WanderProfiler();
		profiler.record(3000, 3200, 0);
		profiler.record(3010, 3208, 0);

		WanderProfiler restored = new WanderProfiler(profiler.exportState());

		WanderProfile profile = restored.toProfile();
		assertEquals(3005, profile.getSpawnX());
		assertEquals(3204, profile.getSpawnY());
		assertEquals(5, profile.getRadius());
		assertEquals(2, profile.getSampleCount());
		assertEquals(2, profile.getWalkedTiles().length);
	}
}

package com.pluginideahub.npctracker;

import static org.junit.Assert.assertEquals;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class TrackColorsTest
{
	@Test
	public void assignsDistinctIndicesToDifferentNpcs()
	{
		TrackColors colors = new TrackColors();
		assertEquals(0, colors.assign(100));
		assertEquals(1, colors.assign(200));
		assertEquals(2, colors.assign(300));
	}

	@Test
	public void sameNpcKeepsItsIndex()
	{
		TrackColors colors = new TrackColors();
		int first = colors.assign(100);
		colors.assign(200);
		assertEquals(first, colors.assign(100));
	}

	@Test
	public void releasingFreesTheSlotForReuse()
	{
		TrackColors colors = new TrackColors();
		colors.assign(100); // slot 0
		colors.assign(200); // slot 1
		colors.release(100);
		assertEquals(0, colors.assign(300)); // reuses the freed slot
	}

	@Test
	public void colorMatchesAssignedPaletteEntry()
	{
		TrackColors colors = new TrackColors();
		int index = colors.assign(555);
		assertEquals(TrackColors.PALETTE[index], colors.color(555));
	}

	@Test
	public void importRestoresAssignmentsAndNextAssignAvoidsThem()
	{
		TrackColors colors = new TrackColors();
		Map<Integer, Integer> saved = new HashMap<>();
		saved.put(100, 3);
		colors.importAssignments(saved);

		assertEquals(TrackColors.PALETTE[3], colors.color(100));
		assertEquals(0, colors.assign(200)); // slot 3 is taken, 0 is free
	}
}

