package com.pluginideahub.npctracker;

import java.util.function.Consumer;
import java.util.function.Predicate;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuEntryAdded;

/**
 * Adds a "Track wander" / "Stop tracking" right-click option to NPCs, injected once per menu build
 * off the NPC's "Examine" row. Tracking is decided by the supplied predicate/consumer, which key on
 * NPC type so a boss stays tracked across respawns.
 */
public final class TrackMenuInjector
{
	private static final String EXAMINE_OPTION = "Examine";
	private static final String TRACK_OPTION = "Track wander";
	private static final String UNTRACK_OPTION = "Stop tracking";

	private final Client client;
	private final Predicate<NPC> isTracked;
	private final Consumer<NPC> onToggle;

	public TrackMenuInjector(Client client, Predicate<NPC> isTracked, Consumer<NPC> onToggle)
	{
		this.client = client;
		this.isTracked = isTracked;
		this.onToggle = onToggle;
	}

	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry entry = event.getMenuEntry();
		NPC npc = entry.getNpc();
		if (npc == null || !EXAMINE_OPTION.equals(entry.getOption()))
		{
			return;
		}

		String label = isTracked.test(npc) ? UNTRACK_OPTION : TRACK_OPTION;
		client.createMenuEntry(-1)
			.setOption(label)
			.setTarget(entry.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(clicked -> onToggle.accept(npc));
	}
}

package com.pluginideahub.npctracker;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Right-click "Track wander" on any NPC and this plugin watches where it stands each tick, then —
 * once it has moved around enough — draws its inferred spawn tile and wander-radius square on the
 * ground, and optionally the trail of every tile it has walked on. What it learns (and which NPCs
 * are tracked) is saved to config, so it survives a logout, world hop, or client restart.
 */
@PluginDescriptor(
	name = "NPC Tracker",
	description = "Track an NPC and it works out its spawn tile, wander radius, and walked tiles - saved across logouts.",
	tags = {"npc", "wander", "spawn", "radius", "tile", "boss"}
)
public class NpcTrackerPlugin extends Plugin
{
	private static final int AUTOSAVE_INTERVAL_TICKS = 50;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private NpcTrackerConfig config;

	// NPC composition ids the user has tracked. Tracking is by type, so a boss stays tracked when it
	// respawns with a new scene index.
	private final Set<Integer> trackedCompositions = new HashSet<>();
	private final TrackColors trackColors = new TrackColors();

	private WanderTracker wanderTracker;
	private WanderOverlay wanderOverlay;
	private TrackMenuInjector menuInjector;
	private WanderStore store;
	private int ticksSinceSave;

	@Provides
	NpcTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NpcTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		store = new WanderStore(configManager, gson);
		wanderTracker = new WanderTracker(client, trackedCompositions::contains);

		SavedState saved = store.load();
		if (saved != null)
		{
			if (saved.tracked != null)
			{
				trackedCompositions.addAll(saved.tracked);
			}
			if (saved.profilers != null)
			{
				wanderTracker.importProfilers(saved.profilers);
			}
			trackColors.importAssignments(saved.colors);
		}
		// Make sure every restored track has a colour, even if loaded from an older save without them.
		for (int id : trackedCompositions)
		{
			trackColors.assign(id);
		}

		wanderOverlay = new WanderOverlay(client, config, wanderTracker, trackColors::color);
		overlayManager.add(wanderOverlay);
		menuInjector = new TrackMenuInjector(client, this::isTracked, this::toggleTracking);
	}

	@Override
	protected void shutDown()
	{
		save();
		if (wanderOverlay != null)
		{
			overlayManager.remove(wanderOverlay);
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		menuInjector.onMenuEntryAdded(event);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		wanderTracker.onGameTick();
		if (++ticksSinceSave >= AUTOSAVE_INTERVAL_TICKS)
		{
			ticksSinceSave = 0;
			save();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		wanderTracker.onNpcSpawned(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Persist the instant we leave the world, so a logout or hop never loses the session's data.
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			save();
		}
	}

	private boolean isTracked(NPC npc)
	{
		return trackedCompositions.contains(compositionId(npc));
	}

	private void toggleTracking(NPC npc)
	{
		int id = compositionId(npc);
		if (!trackedCompositions.remove(id))
		{
			trackedCompositions.add(id);
			trackColors.assign(id);
		}
		else
		{
			// Untracked: drop the box and its accumulated estimate so a re-track starts fresh, and
			// free its colour slot for the next NPC.
			wanderTracker.forget(id);
			trackColors.release(id);
		}
		save();
	}

	private void save()
	{
		if (store == null || wanderTracker == null)
		{
			return;
		}
		SavedState state = new SavedState();
		state.tracked = new HashSet<>(trackedCompositions);
		state.profilers = wanderTracker.exportProfilers();
		state.colors = trackColors.export();
		store.save(state);
	}

	private static int compositionId(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			composition = npc.getComposition();
		}
		return composition == null ? -1 : composition.getId();
	}
}

package com.pluginideahub.npctracker;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("npctracker")
public interface NpcTrackerConfig extends Config
{
	@ConfigItem(
		keyName = "showWanderBox",
		name = "Show wander box",
		description = "Outline a tracked NPC's inferred spawn tile and wander radius on the ground.",
		position = 0
	)
	default boolean showWanderBox()
	{
		return false;
	}

	@ConfigItem(
		keyName = "wanderMinSamples",
		name = "Warm-up (ticks)",
		description = "How many game ticks to watch a tracked NPC before drawing its box. The box keeps " +
			"growing as it wanders further, so give it time to reach its corners.",
		position = 1
	)
	default int wanderMinSamples()
	{
		return 20;
	}

	@Alpha
	@ConfigItem(
		keyName = "wanderBoxColor",
		name = "Wander box colour",
		description = "Colour of the wander radius outline.",
		position = 2
	)
	default Color wanderBoxColor()
	{
		return new Color(0, 224, 255, 120);
	}

	@Alpha
	@ConfigItem(
		keyName = "wanderSpawnColor",
		name = "Spawn tile colour",
		description = "Colour of the inferred spawn tile at the centre of the box.",
		position = 3
	)
	default Color wanderSpawnColor()
	{
		return new Color(255, 120, 0, 200);
	}

	@ConfigItem(
		keyName = "wanderShowInfo",
		name = "Show readout",
		description = "Label the spawn tile with its coordinates, the inferred radius, and the sample count.",
		position = 4
	)
	default boolean wanderShowInfo()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showWalkedTiles",
		name = "Show walked tiles",
		description = "Shade every distinct tile a tracked NPC has been seen standing on (its trail). " +
			"Works on its own, with or without the wander box.",
		position = 5
	)
	default boolean showWalkedTiles()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "walkedTileColor",
		name = "Walked tile colour",
		description = "Colour of the walked-tiles trail. Used for all NPCs when \"Colour per NPC\" is off; " +
			"when it's on, only this colour's opacity is used and the hue comes from the per-NPC palette.",
		position = 6
	)
	default Color walkedTileColor()
	{
		return new Color(0, 200, 120, 70);
	}

	@ConfigItem(
		keyName = "colorPerNpc",
		name = "Colour per NPC",
		description = "Give each tracked NPC its own colour so several can be told apart. Turn off to draw " +
			"every NPC in the single colours set above.",
		position = 7
	)
	default boolean colorPerNpc()
	{
		return true;
	}
}

package com.pluginideahub.npctracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Map;
import java.util.function.IntFunction;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws, for each tracked NPC observed long enough, its walked-tiles trail and/or its inferred spawn
 * tile + wander-radius square, as ground outlines. When "colour per NPC" is on, each NPC type is
 * drawn in its own palette hue (keeping the configured per-element opacity); otherwise the single
 * configured colours are used. Renders nothing until there are samples, or when off the current
 * plane / outside the loaded scene.
 */
public final class WanderOverlay extends Overlay
{
	private final Client client;
	private final NpcTrackerConfig config;
	private final WanderTracker tracker;
	private final IntFunction<Color> paletteColor;

	public WanderOverlay(Client client, NpcTrackerConfig config, WanderTracker tracker, IntFunction<Color> paletteColor)
	{
		this.client = client;
		this.config = config;
		this.tracker = tracker;
		this.paletteColor = paletteColor;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean showBox = config.showWanderBox();
		boolean showTiles = config.showWalkedTiles();
		if (!showBox && !showTiles)
		{
			return null;
		}

		boolean perNpc = config.colorPerNpc();

		// minSamples 1 so the walked-tiles trail shows from the start; the box waits for warm-up below.
		for (Map.Entry<Integer, WanderProfile> entry : tracker.profiles(1).entrySet())
		{
			WanderProfile profile = entry.getValue();
			if (profile.getPlane() != client.getPlane())
			{
				continue;
			}

			Color base = perNpc ? paletteColor.apply(entry.getKey()) : null;

			if (showTiles)
			{
				Color tileColor = perNpc ? tint(base, config.walkedTileColor().getAlpha()) : config.walkedTileColor();
				renderWalkedTiles(graphics, profile, tileColor);
			}

			if (showBox && profile.getSampleCount() >= config.wanderMinSamples())
			{
				Color boxColor = perNpc ? tint(base, config.wanderBoxColor().getAlpha()) : config.wanderBoxColor();
				Color spawnColor = perNpc ? tint(base, config.wanderSpawnColor().getAlpha()) : config.wanderSpawnColor();
				renderBox(graphics, profile, boxColor, spawnColor);
			}
		}
		return null;
	}

	private void renderWalkedTiles(Graphics2D graphics, WanderProfile profile, Color color)
	{
		for (long packed : profile.getWalkedTiles())
		{
			WorldPoint tile = new WorldPoint(WanderProfile.tileX(packed), WanderProfile.tileY(packed), profile.getPlane());
			LocalPoint local = LocalPoint.fromWorld(client, tile);
			if (local == null)
			{
				continue;
			}
			Polygon poly = Perspective.getCanvasTilePoly(client, local);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, color);
			}
		}
	}

	private void renderBox(Graphics2D graphics, WanderProfile profile, Color boxColor, Color spawnColor)
	{
		WorldPoint spawn = new WorldPoint(profile.getSpawnX(), profile.getSpawnY(), profile.getPlane());
		LocalPoint spawnLocal = LocalPoint.fromWorld(client, spawn);
		if (spawnLocal == null)
		{
			return;
		}

		// Odd size (2r+1) keeps the area square centred on the spawn tile.
		Polygon box = Perspective.getCanvasTileAreaPoly(client, spawnLocal, profile.getRadius() * 2 + 1);
		if (box != null)
		{
			OverlayUtil.renderPolygon(graphics, box, boxColor);
		}

		Polygon spawnTile = Perspective.getCanvasTilePoly(client, spawnLocal);
		if (spawnTile != null)
		{
			OverlayUtil.renderPolygon(graphics, spawnTile, spawnColor);
		}

		if (config.wanderShowInfo())
		{
			String label = spawn.getX() + "," + spawn.getY() + "  r" + profile.getRadius()
				+ "  (" + profile.getSampleCount() + ")";
			Point textLocation = Perspective.getCanvasTextLocation(client, graphics, spawnLocal, label, 0);
			if (textLocation != null)
			{
				OverlayUtil.renderTextLocation(graphics, textLocation, label, spawnColor);
			}
		}
	}

	private static Color tint(Color base, int alpha)
	{
		return new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);
	}
}

package com.pluginideahub.npctracker;

/**
 * Immutable snapshot of what has been inferred about one NPC's wandering: the tile its wander box is
 * centred on (the estimated spawn point), the box's half-width in tiles (the wander radius), how
 * many position samples that estimate is based on, and every distinct tile the NPC has been seen
 * standing on (for the walked-tiles trail).
 *
 * <p>The spawn point is the centre of the bounding box of every observed tile, and the radius is the
 * largest Chebyshev (king-move) distance from that centre. Given enough samples this converges on
 * the NPC's true server-side spawn tile and wander range, because a wander box is symmetric about
 * the spawn.
 */
public final class WanderProfile
{
	private final int spawnX;
	private final int spawnY;
	private final int plane;
	private final int radius;
	private final int sampleCount;
	private final long[] walkedTiles;

	public WanderProfile(int spawnX, int spawnY, int plane, int radius, int sampleCount, long[] walkedTiles)
	{
		this.spawnX = spawnX;
		this.spawnY = spawnY;
		this.plane = plane;
		this.radius = radius;
		this.sampleCount = sampleCount;
		this.walkedTiles = walkedTiles;
	}

	public int getSpawnX()
	{
		return spawnX;
	}

	public int getSpawnY()
	{
		return spawnY;
	}

	public int getPlane()
	{
		return plane;
	}

	public int getRadius()
	{
		return radius;
	}

	public int getSampleCount()
	{
		return sampleCount;
	}

	/** Packed (x, y) tiles the NPC has been seen standing on, all on this profile's plane. */
	public long[] getWalkedTiles()
	{
		return walkedTiles;
	}

	public static long packTile(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	public static int tileX(long packed)
	{
		return (int) (packed >> 32);
	}

	public static int tileY(long packed)
	{
		return (int) packed;
	}
}

package com.pluginideahub.npctracker;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Serializable snapshot of everything the plugin needs to survive a logout, world hop, or restart:
 * which NPC types are being tracked, and each one's accumulated wander estimate.
 */
final class SavedState
{
	Set<Integer> tracked = new HashSet<>();
	Map<Integer, WanderProfiler.State> profilers = new HashMap<>();
	Map<Integer, Integer> colors = new HashMap<>();
}

package com.pluginideahub.npctracker;

import java.awt.Color;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Assigns each tracked NPC type a distinct colour from a fixed palette, so several tracked NPCs can
 * be told apart on screen. A newly-tracked NPC takes the lowest palette slot not currently in use,
 * and untracking frees that slot for reuse; assignments are stable and persisted, so an NPC keeps
 * its colour across a logout. With more tracked NPCs than palette entries the colours wrap around.
 *
 * <p>Only the hue (RGB) comes from the palette — the overlay applies its own alpha per element, so
 * the configured trail/box/spawn opacities still apply.
 */
final class TrackColors
{
	static final Color[] PALETTE = {
		new Color(255, 96, 96),    // red
		new Color(96, 176, 255),   // blue
		new Color(96, 224, 128),   // green
		new Color(255, 208, 64),   // yellow
		new Color(200, 128, 255),  // purple
		new Color(255, 144, 48),   // orange
		new Color(64, 224, 224),   // cyan
		new Color(255, 128, 192),  // pink
	};

	private final Map<Integer, Integer> indexByComposition = new HashMap<>();

	/** Assigns (or returns the existing) palette index for an NPC type. */
	int assign(int composition)
	{
		Integer existing = indexByComposition.get(composition);
		if (existing != null)
		{
			return existing;
		}
		int index = lowestFreeIndex();
		indexByComposition.put(composition, index);
		return index;
	}

	void release(int composition)
	{
		indexByComposition.remove(composition);
	}

	/** The palette colour for an NPC type, falling back to a stable hash if it was never assigned. */
	Color color(int composition)
	{
		Integer index = indexByComposition.get(composition);
		int i = index != null ? index : Math.floorMod(composition, PALETTE.length);
		return PALETTE[i % PALETTE.length];
	}

	Map<Integer, Integer> export()
	{
		return new HashMap<>(indexByComposition);
	}

	void importAssignments(Map<Integer, Integer> saved)
	{
		indexByComposition.clear();
		if (saved != null)
		{
			indexByComposition.putAll(saved);
		}
	}

	private int lowestFreeIndex()
	{
		Set<Integer> used = new HashSet<>(indexByComposition.values());
		int index = 0;
		while (used.contains(index))
		{
			index++;
		}
		return index;
	}
}

package com.pluginideahub.npctracker;

import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Accumulates the tiles one NPC has been seen standing on and, from that alone, estimates where it
 * spawned and how far it wanders. Feed it the NPC's world tile once per game tick (and once when it
 * spawns); read the running estimate with {@link #toProfile()}.
 *
 * <p>Keeps the bounding box (for the spawn/radius estimate) and the set of distinct tiles visited
 * (for the walked-tiles trail). Changing plane (e.g. the NPC walks up a staircase) discards both and
 * starts fresh on the new plane, since a wander area does not span floors. State can be exported and
 * re-imported via {@link State} so it survives a logout.
 */
public final class WanderProfiler
{
	private boolean hasData;
	private int plane;
	private int minX;
	private int maxX;
	private int minY;
	private int maxY;
	private int sampleCount;
	private final Set<Long> visited = new LinkedHashSet<>();

	public WanderProfiler()
	{
	}

	public WanderProfiler(State state)
	{
		hasData = state.hasData;
		plane = state.plane;
		minX = state.minX;
		maxX = state.maxX;
		minY = state.minY;
		maxY = state.maxY;
		sampleCount = state.sampleCount;
		if (state.tiles != null)
		{
			for (long tile : state.tiles)
			{
				visited.add(tile);
			}
		}
	}

	public void record(int x, int y, int plane)
	{
		if (!hasData || plane != this.plane)
		{
			this.plane = plane;
			minX = maxX = x;
			minY = maxY = y;
			sampleCount = 0;
			hasData = true;
			visited.clear();
		}
		else
		{
			if (x < minX)
			{
				minX = x;
			}
			if (x > maxX)
			{
				maxX = x;
			}
			if (y < minY)
			{
				minY = y;
			}
			if (y > maxY)
			{
				maxY = y;
			}
		}
		visited.add(WanderProfile.packTile(x, y));
		sampleCount++;
	}

	public boolean hasData()
	{
		return hasData;
	}

	public int getSampleCount()
	{
		return sampleCount;
	}

	/**
	 * The current estimate, or {@code null} until at least one tile has been recorded.
	 */
	public WanderProfile toProfile()
	{
		if (!hasData)
		{
			return null;
		}
		int spawnX = Math.floorDiv(minX + maxX, 2);
		int spawnY = Math.floorDiv(minY + maxY, 2);
		int radiusX = Math.max(maxX - spawnX, spawnX - minX);
		int radiusY = Math.max(maxY - spawnY, spawnY - minY);
		int radius = Math.max(radiusX, radiusY);
		return new WanderProfile(spawnX, spawnY, plane, radius, sampleCount, tileArray());
	}

	public void reset()
	{
		hasData = false;
		sampleCount = 0;
		visited.clear();
	}

	/** A plain, serializable copy of the internal state, for persistence across a logout. */
	public State exportState()
	{
		return new State(hasData, plane, minX, maxX, minY, maxY, sampleCount, tileArray());
	}

	private long[] tileArray()
	{
		long[] tiles = new long[visited.size()];
		int i = 0;
		for (long tile : visited)
		{
			tiles[i++] = tile;
		}
		return tiles;
	}

	/** Flat, Gson-friendly mirror of a profiler's internal state (public fields, no-arg constructor). */
	public static final class State
	{
		public boolean hasData;
		public int plane;
		public int minX;
		public int maxX;
		public int minY;
		public int maxY;
		public int sampleCount;
		public long[] tiles;

		public State()
		{
		}

		public State(boolean hasData, int plane, int minX, int maxX, int minY, int maxY, int sampleCount, long[] tiles)
		{
			this.hasData = hasData;
			this.plane = plane;
			this.minX = minX;
			this.maxX = maxX;
			this.minY = minY;
			this.maxY = maxY;
			this.sampleCount = sampleCount;
			this.tiles = tiles;
		}
	}
}

package com.pluginideahub.npctracker;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.coords.WorldPoint;

/**
 * Watches every NPC the user is currently tracking and, per NPC type (composition id), builds up a
 * {@link WanderProfiler} from where that NPC stands each game tick. This is how the plugin "figures
 * out" an NPC's spawn tile and wander radius just by observing it for a while.
 *
 * <p>Keyed by composition id (not scene index) so a boss that dies and respawns keeps accumulating
 * into the same profile — it respawns at the same world tile, so the box stays valid. The trade-off
 * is that several loose NPCs of one type would share (and inflate) one box; for the intended use of
 * profiling a single tracked NPC that does not bite.
 */
public final class WanderTracker
{
	private final Client client;
	private final IntPredicate isTracked;
	private final Map<Integer, WanderProfiler> profilers = new HashMap<>();

	public WanderTracker(Client client, IntPredicate isTracked)
	{
		this.client = client;
		this.isTracked = isTracked;
	}

	public void onGameTick()
	{
		for (NPC npc : client.getNpcs())
		{
			record(npc);
		}
	}

	/** Seeds a fresh spawn's home tile the instant it appears (à la the npc-spawns plugin). */
	public void onNpcSpawned(NPC npc)
	{
		record(npc);
	}

	private void record(NPC npc)
	{
		if (npc == null)
		{
			return;
		}
		int composition = compositionId(npc);
		if (composition < 0 || !isTracked.test(composition))
		{
			return;
		}
		WorldPoint location = npc.getWorldLocation();
		if (location == null)
		{
			return;
		}
		profilers.computeIfAbsent(composition, k -> new WanderProfiler())
			.record(location.getX(), location.getY(), location.getPlane());
	}

	/**
	 * A snapshot of every currently-tracked NPC's estimated wander profile that has reached at least
	 * {@code minSamples} observations. Untracked NPCs are omitted, so clearing a Track hides its box.
	 */
	public Map<Integer, WanderProfile> profiles(int minSamples)
	{
		Map<Integer, WanderProfile> out = new LinkedHashMap<>();
		for (Map.Entry<Integer, WanderProfiler> entry : profilers.entrySet())
		{
			if (!isTracked.test(entry.getKey()))
			{
				continue;
			}
			WanderProfiler profiler = entry.getValue();
			if (profiler.getSampleCount() < minSamples)
			{
				continue;
			}
			WanderProfile profile = profiler.toProfile();
			if (profile != null)
			{
				out.put(entry.getKey(), profile);
			}
		}
		return out;
	}

	/** Discards accumulated data for one NPC type, so its estimate starts fresh next time. */
	public void forget(int compositionId)
	{
		profilers.remove(compositionId);
	}

	public void clear()
	{
		profilers.clear();
	}

	/** Serializable copy of every profiler, keyed by composition id, for saving across a logout. */
	public Map<Integer, WanderProfiler.State> exportProfilers()
	{
		Map<Integer, WanderProfiler.State> out = new HashMap<>();
		for (Map.Entry<Integer, WanderProfiler> entry : profilers.entrySet())
		{
			out.put(entry.getKey(), entry.getValue().exportState());
		}
		return out;
	}

	/** Replaces all profilers with ones rebuilt from a saved snapshot (used on start-up). */
	public void importProfilers(Map<Integer, WanderProfiler.State> saved)
	{
		profilers.clear();
		for (Map.Entry<Integer, WanderProfiler.State> entry : saved.entrySet())
		{
			if (entry.getValue() != null)
			{
				profilers.put(entry.getKey(), new WanderProfiler(entry.getValue()));
			}
		}
	}

	private static int compositionId(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			composition = npc.getComposition();
		}
		return composition == null ? -1 : composition.getId();
	}
}

package com.pluginideahub.npctracker;

import com.google.gson.Gson;
import net.runelite.client.config.ConfigManager;

/**
 * Persists the tracked NPC set and every wander estimate to RuneLite's config, so a logout, world
 * hop, or client restart doesn't throw away what's been learned. Stored as one JSON blob under the
 * plugin's config group with no {@code @ConfigItem}, so it stays out of the settings UI — the same
 * approach the Ground Markers plugin uses for its tiles.
 */
final class WanderStore
{
	private static final String GROUP = "npctracker";
	private static final String KEY = "savedstate";

	private final ConfigManager configManager;
	private final Gson gson;

	WanderStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	void save(SavedState state)
	{
		configManager.setConfiguration(GROUP, KEY, gson.toJson(state));
	}

	/** The saved state, or {@code null} if nothing has been saved yet (or it failed to parse). */
	SavedState load()
	{
		String json = configManager.getConfiguration(GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, SavedState.class);
		}
		catch (Exception e)
		{
			return null;
		}
	}
}
